	private static function evaluation_followup_handoff( array $decisions ) {
		$groups = array(
			'alignment_required' => array(),
			'semantic_review_required' => array(),
			'behavioral_review_required' => array(),
			'read_candidates' => array(),
			'inactive' => array(),
			'other_followup' => array(),
		);
		$alignment = array( 'runtime_alignment_required', 'runtime_evidence_unstable', 'evidence_unavailable', 'contract_discovery_required' );
		$semantic = array( 'contract_evidence_review', 'runtime_contract_evidence_captured', 'semantic_attestation_required' );
		$behavioral = array( 'behavioral_recertification_required' );
		$read_candidates = array( 'read_contract_candidate', 'redacted_read_contract_candidate' );
		foreach ( $decisions as $row ) {
			$family = isset( $row['family'] ) ? sanitize_key( (string) $row['family'] ) : '';
			$state = isset( $row['state'] ) ? sanitize_key( (string) $row['state'] ) : '';
			if ( '' === $family ) continue;
			if ( 'not_active' === $state ) $groups['inactive'][] = $family;
			elseif ( in_array( $state, $alignment, true ) ) $groups['alignment_required'][] = $family;
			elseif ( in_array( $state, $semantic, true ) ) $groups['semantic_review_required'][] = $family;
			elseif ( in_array( $state, $behavioral, true ) ) $groups['behavioral_review_required'][] = $family;
			elseif ( in_array( $state, $read_candidates, true ) ) $groups['read_candidates'][] = $family;
			else $groups['other_followup'][] = $family;
		}
		foreach ( $groups as $key => $families ) {
			$families = array_values( array_unique( array_filter( array_map( 'sanitize_key', $families ) ) ) );
			sort( $families, SORT_STRING );
			$groups[ $key ] = $families;
		}
		$followup = array_values( array_unique( array_merge(
			$groups['alignment_required'],
			$groups['semantic_review_required'],
			$groups['behavioral_review_required'],
			$groups['read_candidates'],
			$groups['other_followup']
		) ) );
		sort( $followup, SORT_STRING );
		return array(
			'contract' => 'mad4b.functional-gap-decision-handoff.v1',
			'followup_required' => ! empty( $followup ),
			'followup_count' => count( $followup ),
			'followup_families' => $followup,
			'groups' => $groups,
			'authorizing' => false,
			'mutation_granted' => false,
			'promotion_granted' => false,
		);
	}

	private static function decision_fingerprint( array $repository, array $policy, array $decisions, $runtime_evidence_fingerprint = '' ) {
		$payload = array(
			'contract' => self::EVALUATION_CONTRACT,
			'policy_sha256' => isset( $policy['sha256'] ) ? (string) $policy['sha256'] : '',
			'repository_evidence_sha256' => isset( $repository['evidence_sha256'] ) ? (string) $repository['evidence_sha256'] : '',
			'repository_source_commit_sha' => isset( $repository['source_commit_sha'] ) ? (string) $repository['source_commit_sha'] : '',
			'runtime_evidence_fingerprint' => (string) $runtime_evidence_fingerprint,
			'decisions' => $decisions,
		);
		return self::canonical_digest( $payload );
	}

	private static function evaluate( array $repository, array $runtime ) {
		$decisions = array();
		$evaluation_blockers = array();
		$repo_families = isset( $repository['families'] ) && is_array( $repository['families'] ) ? $repository['families'] : array();
		$policy = self::policy();
		$policy_families = isset( $policy['data']['families'] ) && is_array( $policy['data']['families'] ) ? $policy['data']['families'] : array();

		if ( empty( $repository['valid'] ) || empty( $policy['valid'] ) ) {
			foreach ( array_keys( $policy_families ) as $family ) {
				$decisions[] = self::decision( sanitize_key( (string) $family ), 'evidence_unavailable', 'repository_evidence_or_policy_missing_or_stale' );
			}
			$blockers = array_merge(
				isset( $repository['blockers'] ) ? (array) $repository['blockers'] : array(),
				isset( $policy['blockers'] ) ? (array) $policy['blockers'] : array()
			);
			$blockers = array_values( array_unique( array_filter( array_map( 'sanitize_key', $blockers ) ) ) );
			usort( $decisions, static function ( $a, $b ) { return strcmp( isset( $a['family'] ) ? (string) $a['family'] : '', isset( $b['family'] ) ? (string) $b['family'] : '' ); } );
			$runtime_evidence_fingerprint = self::runtime_evidence_fingerprint( $runtime );
			$decision_fingerprint = self::decision_fingerprint( $repository, $policy, $decisions, $runtime_evidence_fingerprint );
			$handoff = self::evaluation_followup_handoff( $decisions );
			return array(
				'contract' => self::EVALUATION_CONTRACT,
				'evaluation_complete' => false,
				'ready' => false,
				'ready_semantics' => 'backward_compatible_alias_for_evaluation_complete_not_provider_certification',
				'followup_required' => ! empty( $handoff['followup_required'] ),
				'followup_count' => isset( $handoff['followup_count'] ) ? (int) $handoff['followup_count'] : 0,
				'decision_handoff' => $handoff,
				'promotion_authorized' => false,
				'production_mutation' => false,
				'policy_contract' => isset( $policy['contract'] ) ? $policy['contract'] : '',
				'policy_sha256' => isset( $policy['sha256'] ) ? $policy['sha256'] : '',
				'runtime_evidence_fingerprint' => $runtime_evidence_fingerprint,
				'decision_fingerprint' => $decision_fingerprint,
				'decisions' => $decisions,
				'blockers' => $blockers,
			);
		}

		$routes = self::route_methods( $runtime );
		$route_security = self::route_security( $runtime );
		$options = isset( $runtime['option_presence'] ) && is_array( $runtime['option_presence'] ) ? $runtime['option_presence'] : array();
		$runtime_evidence_fingerprint = self::runtime_evidence_fingerprint( $runtime );
		if ( ! preg_match( '/^[a-f0-9]{64}$/', $runtime_evidence_fingerprint ) ) $evaluation_blockers[] = 'runtime_evidence_fingerprint_unavailable';

		foreach ( $policy_families as $family_id => $rule ) {
			$family = sanitize_key( (string) $family_id );
			if ( '' === $family || ! is_array( $rule ) ) continue;
			$mode = isset( $rule['evaluation_mode'] ) ? sanitize_key( (string) $rule['evaluation_mode'] ) : '';
			$rows = self::active_plugins( $runtime, $family );
			$versions = self::plugin_versions( $runtime, $family );
			$matches = self::tree_matches( isset( $repo_families[ $family ] ) ? $repo_families[ $family ] : array(), $rows );
			$runtime_tree_evidence = array();
			foreach ( $rows as $row ) {
				$tree = isset( $row['plugin_tree'] ) && is_array( $row['plugin_tree'] ) ? $row['plugin_tree'] : array();
				$runtime_tree_evidence[] = array(
					'plugin_file'=>isset( $row['plugin_file'] ) ? self::normalize_plugin_file( (string) $row['plugin_file'] ) : '',
					'version'=>isset( $row['version'] ) ? (string) $row['version'] : '',
					'tree_sha256'=>isset( $tree['tree_sha256'] ) ? (string) $tree['tree_sha256'] : '',
					'file_count'=>isset( $tree['file_count'] ) ? (int) $tree['file_count'] : 0,
					'total_bytes'=>isset( $tree['total_bytes'] ) ? (int) $tree['total_bytes'] : 0,
					'scan_stable'=>! empty( $tree['scan_stable'] ),
					'comparison'=>isset( $tree['comparison'] ) ? sanitize_key( (string) $tree['comparison'] ) : '',
				);
			}
			usort( $runtime_tree_evidence, static function ( $a, $b ) { return strcmp( (string) $a['plugin_file'], (string) $b['plugin_file'] ); } );
			$base_extra = array( 'evaluation_mode'=>$mode, 'runtime_versions'=>$versions, 'runtime_tree_evidence'=>$runtime_tree_evidence, 'exact_tree_matches'=>$matches );

			if ( empty( $rows ) ) {
				$decisions[] = self::decision( $family, 'not_active', 'provider_not_active', $base_extra );
				continue;
			}
			if ( ! self::runtime_rows_stable( $rows ) ) {
				$decisions[] = self::decision( $family, 'runtime_evidence_unstable', 'runtime_tree_changed_or_scan_failed', $base_extra );
				continue;
			}

			switch ( $mode ) {
				case 'bounded_read_routes':
					$required = isset( $rule['required_get_routes'] ) && is_array( $rule['required_get_routes'] ) ? array_values( array_filter( array_map( 'sanitize_text_field', $rule['required_get_routes'] ) ) ) : array();
					$missing = array();
					$insecure = array();
					$permission_callback_mismatch = array();
					$permission_evidence = array();
					$require_non_public = ! empty( $rule['require_non_public_permissions'] );
					$required_callbacks = isset( $rule['required_get_permission_callbacks'] ) && is_array( $rule['required_get_permission_callbacks'] ) ? $rule['required_get_permission_callbacks'] : array();
					foreach ( $required as $route ) {
						if ( ! isset( $routes[ $route ] ) || ! in_array( 'GET', $routes[ $route ], true ) ) { $missing[] = $route; continue; }
						$security = isset( $route_security[ $route ] ) && is_array( $route_security[ $route ] ) ? $route_security[ $route ] : array( 'callbacks'=>array(), 'missing'=>true, 'public'=>false );
						$actual_callbacks = isset( $security['callbacks'] ) && is_array( $security['callbacks'] ) ? array_values( array_unique( array_map( 'strtolower', array_map( 'strval', $security['callbacks'] ) ) ) ) : array();
						$expected_callbacks = isset( $required_callbacks[ $route ] ) && is_array( $required_callbacks[ $route ] ) ? array_values( array_unique( array_map( 'strtolower', array_map( 'strval', $required_callbacks[ $route ] ) ) ) ) : array();
						sort( $actual_callbacks, SORT_STRING );
						sort( $expected_callbacks, SORT_STRING );
						$security['expected_callbacks'] = $expected_callbacks;
						$security['callback_identity_match'] = ! empty( $expected_callbacks ) && $actual_callbacks === $expected_callbacks;
						$permission_evidence[ $route ] = $security;
						if ( $require_non_public && ( ! empty( $security['missing'] ) || ! empty( $security['public'] ) || empty( $actual_callbacks ) ) ) $insecure[] = $route;
						if ( empty( $expected_callbacks ) || $actual_callbacks !== $expected_callbacks ) $permission_callback_mismatch[] = $route;
					}
					ksort( $permission_evidence, SORT_STRING );
					$extra = array_merge( $base_extra, array(
						'missing_get_routes'=>$missing,
						'insecure_get_routes'=>$insecure,
						'permission_callback_mismatch'=>$permission_callback_mismatch,
						'route_permission_evidence'=>$permission_evidence,
						'safe_now'=>isset( $rule['safe_now'] ) && is_array( $rule['safe_now'] ) ? array_values( $rule['safe_now'] ) : array(),
						'blocked'=>isset( $rule['blocked'] ) && is_array( $rule['blocked'] ) ? array_values( $rule['blocked'] ) : array(),
					) );
					if ( count( $matches ) === count( $rows ) && empty( $missing ) && empty( $insecure ) && empty( $permission_callback_mismatch ) ) $decisions[] = self::decision( $family, 'read_contract_candidate', 'exact_runtime_tree_required_get_routes_and_permission_callbacks_verified', $extra );
					else $decisions[] = self::decision( $family, 'contract_discovery_required', 'exact_runtime_tree_routes_or_permission_callback_boundary_unverified', $extra );
					break;

				case 'redacted_status':
					$secret_keys = isset( $rule['redacted_secret_option_keys'] ) && is_array( $rule['redacted_secret_option_keys'] ) ? array_values( array_filter( array_map( 'sanitize_text_field', $rule['redacted_secret_option_keys'] ) ) ) : array();
					$status_keys = isset( $rule['required_status_option_keys'] ) && is_array( $rule['required_status_option_keys'] ) ? array_values( array_filter( array_map( 'sanitize_text_field', $rule['required_status_option_keys'] ) ) ) : array();
					$secret_ok = ! empty( $secret_keys );
					foreach ( $secret_keys as $key ) {
						if ( ! isset( $options[ $key ] ) || true !== ( $options[ $key ]['redacted'] ?? false ) || false !== ( $options[ $key ]['value_read'] ?? null ) || 'omitted_secret_value' !== (string) ( $options[ $key ]['probe'] ?? '' ) ) $secret_ok = false;
					}
					$status_model = ! empty( $status_keys );
					foreach ( $status_keys as $key ) {
						if ( ! array_key_exists( $key, $options ) || empty( $options[ $key ]['exists'] ) ) $status_model = false;
					}
					$extra = array_merge( $base_extra, array(
						'secret_redaction_verified'=>$secret_ok,
						'status_model_verified'=>$status_model,
						'safe_now'=>isset( $rule['safe_now'] ) && is_array( $rule['safe_now'] ) ? array_values( $rule['safe_now'] ) : array(),
						'blocked'=>isset( $rule['blocked'] ) && is_array( $rule['blocked'] ) ? array_values( $rule['blocked'] ) : array(),
					) );
					if ( count( $matches ) === count( $rows ) && $secret_ok && $status_model ) $decisions[] = self::decision( $family, 'redacted_read_contract_candidate', 'exact_runtime_tree_and_secret_values_unread', $extra );
					else $decisions[] = self::decision( $family, 'contract_discovery_required', 'exact_runtime_tree_or_redacted_status_model_unverified', $extra );
					break;

				case 'exact_tree_review':
					if ( count( $matches ) === count( $rows ) ) $decisions[] = self::decision( $family, 'contract_evidence_review', 'exact_runtime_tree_verified_but_semantic_contract_not_yet_promoted', $base_extra );
					else $decisions[] = self::decision( $family, 'runtime_alignment_required', 'live_runtime_tree_does_not_match_repository_evidence', $base_extra );
					break;

				case 'runtime_only':
					$plugin_files = array();
					$tree_hashes = array();
					foreach ( $rows as $row ) {
						$plugin_files[] = isset( $row['plugin_file'] ) ? (string) $row['plugin_file'] : '';
						$tree_hashes[] = isset( $row['plugin_tree']['tree_sha256'] ) ? (string) $row['plugin_tree']['tree_sha256'] : '';
					}
					$decisions[] = self::decision( $family, 'runtime_contract_evidence_captured', 'runtime_only_provider_requires_semantic_contract_before_specialized_surface', array_merge( $base_extra, array( 'plugin_files'=>$plugin_files, 'tree_sha256'=>$tree_hashes ) ) );
					break;

				case 'premium_semantic':
					if ( count( $matches ) !== count( $rows ) ) {
						$decisions[] = self::decision( $family, 'runtime_alignment_required', 'premium_provider_runtime_tree_does_not_match_repository_identity', $base_extra );
					} else {
						$decisions[] = self::decision( $family, 'semantic_attestation_required', 'premium_provider_exact_repository_identity_verified_semantic_review_still_required', $base_extra );
					}
					break;

				case 'composite_behavioral':
					$expected_artifacts = isset( $rule['repository_artifacts'] ) && is_array( $rule['repository_artifacts'] ) ? array_values( array_unique( array_map( 'sanitize_text_field', $rule['repository_artifacts'] ) ) ) : array();
					$matched_artifacts = array();
					foreach ( $matches as $match ) if ( ! empty( $match['repository_archive'] ) ) $matched_artifacts[] = sanitize_text_field( (string) $match['repository_archive'] );
					$matched_artifacts = array_values( array_unique( $matched_artifacts ) );
					sort( $expected_artifacts, SORT_STRING );
					sort( $matched_artifacts, SORT_STRING );
					$component_identity_exact = count( $matches ) === count( $rows ) && $matched_artifacts === $expected_artifacts;
					$composite_extra = array_merge( $base_extra, array(
						'expected_repository_artifacts' => $expected_artifacts,
						'matched_repository_artifacts' => $matched_artifacts,
						'component_identity_exact' => $component_identity_exact,
					) );
					if ( ! $component_identity_exact ) {
						$decisions[] = self::decision( $family, 'runtime_alignment_required', 'composite_provider_runtime_components_do_not_match_repository_identity', $composite_extra );
					} else {
						$decisions[] = self::decision( $family, 'behavioral_recertification_required', 'composite_provider_exact_component_identity_verified_behavioral_execution_contract_still_required', $composite_extra );
					}
					break;

				default:
					$evaluation_blockers[] = 'unsupported_evaluation_mode_' . ( '' !== $mode ? $mode : 'missing' );
					$decisions[] = self::decision( $family, 'evidence_unavailable', 'functional_gap_policy_evaluation_mode_unsupported', $base_extra );
					break;
			}
		}

		usort( $decisions, static function ( $a, $b ) { return strcmp( isset( $a['family'] ) ? (string) $a['family'] : '', isset( $b['family'] ) ? (string) $b['family'] : '' ); } );
		$decision_fingerprint = self::decision_fingerprint( $repository, $policy, $decisions, $runtime_evidence_fingerprint );
		if ( ! preg_match( '/^[a-f0-9]{64}$/', $decision_fingerprint ) ) $evaluation_blockers[] = 'decision_fingerprint_unavailable';

		$counts = array();
		foreach ( $decisions as $row ) {
			$state = isset( $row['state'] ) ? (string) $row['state'] : 'unknown';
			$counts[ $state ] = isset( $counts[ $state ] ) ? $counts[ $state ] + 1 : 1;
		}
		ksort( $counts, SORT_STRING );
		$evaluation_blockers = array_values( array_unique( array_filter( array_map( 'sanitize_key', $evaluation_blockers ) ) ) );

		$handoff = self::evaluation_followup_handoff( $decisions );
		$evaluation_complete = empty( $evaluation_blockers );
		return array(
			'contract' => self::EVALUATION_CONTRACT,
			'evaluation_complete' => $evaluation_complete,
			'ready' => $evaluation_complete,
			'ready_semantics' => 'backward_compatible_alias_for_evaluation_complete_not_provider_certification',
			'followup_required' => ! empty( $handoff['followup_required'] ),
			'followup_count' => isset( $handoff['followup_count'] ) ? (int) $handoff['followup_count'] : 0,
			'decision_handoff' => $handoff,
			'promotion_authorized' => false,
			'production_mutation' => false,
			'policy_contract' => isset( $policy['contract'] ) ? $policy['contract'] : '',
			'policy_sha256' => isset( $policy['sha256'] ) ? $policy['sha256'] : '',
			'runtime_evidence_fingerprint' => $runtime_evidence_fingerprint,
			'decision_fingerprint' => $decision_fingerprint,
			'repository_source_commit_sha' => isset( $repository['source_commit_sha'] ) ? $repository['source_commit_sha'] : '',
			'counts' => $counts,
			'decisions' => $decisions,
			'blockers' => $evaluation_blockers,
		);
	}

	public static function package_integrity_status() {
		$provenance = self::build_provenance();
		$verification = isset( $provenance['package_verification'] ) && is_array( $provenance['package_verification'] ) ? $provenance['package_verification'] : array();
		return array(
			'contract' => 'mad4b.functional-gap-package-integrity.v1',
			'valid' => ! empty( $provenance['valid'] ) && ! empty( $verification['valid'] ),
			'source_commit_sha' => isset( $provenance['source_commit_sha'] ) ? (string) $provenance['source_commit_sha'] : '',
			'build_fingerprint' => isset( $provenance['build_fingerprint'] ) ? (string) $provenance['build_fingerprint'] : '',
			'package_manifest_digest' => isset( $provenance['package_manifest_digest'] ) ? (string) $provenance['package_manifest_digest'] : '',
			'integrity_level' => isset( $verification['integrity_level'] ) ? (string) $verification['integrity_level'] : 'unknown',
			'verified_file_count' => isset( $verification['verified_file_count'] ) ? (int) $verification['verified_file_count'] : 0,
			'verified_bytes' => isset( $verification['verified_bytes'] ) ? (int) $verification['verified_bytes'] : 0,
			'actual_file_count' => isset( $verification['actual_file_count'] ) ? (int) $verification['actual_file_count'] : 0,
			'elapsed_ms' => isset( $verification['elapsed_ms'] ) ? (int) $verification['elapsed_ms'] : 0,
			'external_cryptographic_attestation' => false,
			'blockers' => isset( $provenance['blockers'] ) ? array_values( (array) $provenance['blockers'] ) : array(),
		);
	}

	public static function snapshot() {
		$key = self::runtime_identity_key();
		if ( null !== self::$snapshot && '' !== self::$snapshot_key && hash_equals( self::$snapshot_key, $key ) ) {
			$cached_dynamic = isset( self::$snapshot['snapshot_end_dynamic_surface_sha256'] ) ? strtolower( (string) self::$snapshot['snapshot_end_dynamic_surface_sha256'] ) : '';
			$current_dynamic = strtolower( (string) self::current_dynamic_surface_fingerprint() );
			$dynamic_match = preg_match( '/^[a-f0-9]{64}$/', $cached_dynamic ) && preg_match( '/^[a-f0-9]{64}$/', $current_dynamic ) && hash_equals( $cached_dynamic, $current_dynamic );
			$census_required = ! empty( self::$snapshot['snapshot_census_required'] );
			$census_match = true;
			if ( $census_required ) {
				$cached_census = isset( self::$snapshot['snapshot_end_census']['census_sha256'] ) ? strtolower( (string) self::$snapshot['snapshot_end_census']['census_sha256'] ) : '';
				$current_census = self::current_runtime_census_status();
				$current_census_sha = isset( $current_census['census_sha256'] ) ? strtolower( (string) $current_census['census_sha256'] ) : '';
				$census_match = ! empty( $current_census['valid'] )
					&& preg_match( '/^[a-f0-9]{64}$/', $cached_census )
					&& preg_match( '/^[a-f0-9]{64}$/', $current_census_sha )
					&& hash_equals( $cached_census, $current_census_sha );
			}
			if ( $dynamic_match && $census_match ) return self::$snapshot;
			self::$snapshot = null;
			self::$snapshot_key = '';
		}
		$repository = self::repository_evidence();
		self::$scan_files = 0;
		self::$scan_bytes = 0;
		self::$scan_started_at = microtime( true );
		$runtime = self::runtime_evidence( $repository );
		$start_dynamic_surface = self::runtime_dynamic_surface_fingerprint( $runtime );
		$evaluation = self::evaluate( $repository, $runtime );
		$runtime_census = self::runtime_census_from_runtime( $runtime );
		$end_key = self::runtime_identity_key();
		$end_dynamic_surface = self::current_dynamic_surface_fingerprint();
		$census_required = ! empty( $repository['valid'] );
		$end_census = $census_required ? self::current_runtime_census_status() : array(
			'contract' => 'mad4b.functional-gap-runtime-census.v1',
			'valid' => true,
			'census_sha256' => '',
			'metadata_only' => true,
			'content_rehashed' => false,
			'blockers' => array(),
		);
		$identity_stable = '' !== $key && '' !== $end_key && hash_equals( $key, $end_key );
		$start_census_sha = isset( $runtime_census['census_sha256'] ) ? strtolower( (string) $runtime_census['census_sha256'] ) : '';
		$end_census_sha = isset( $end_census['census_sha256'] ) ? strtolower( (string) $end_census['census_sha256'] ) : '';
		$census_stable = ! $census_required || (
			! empty( $runtime_census['valid'] ) && ! empty( $end_census['valid'] )
			&& preg_match( '/^[a-f0-9]{64}$/', $start_census_sha ) && preg_match( '/^[a-f0-9]{64}$/', $end_census_sha )
			&& hash_equals( $start_census_sha, $end_census_sha )
		);
		$dynamic_surface_stable = preg_match( '/^[a-f0-9]{64}$/', (string) $start_dynamic_surface ) && preg_match( '/^[a-f0-9]{64}$/', (string) $end_dynamic_surface ) && hash_equals( (string) $start_dynamic_surface, (string) $end_dynamic_surface );
		$fixed_point_stable = $identity_stable && $census_stable && $dynamic_surface_stable;
		if ( ! $fixed_point_stable && self::$fixed_point_retry_depth < 1 ) {
			++self::$fixed_point_retry_depth;
			self::$snapshot = null;
			self::$snapshot_key = '';
			$retry = self::snapshot();
			--self::$fixed_point_retry_depth;
			return $retry;
		}
		if ( ! $fixed_point_stable ) {
			$evaluation['ready'] = false;
			$evaluation['promotion_authorized'] = false;
			$evaluation['production_mutation'] = false;
			$evaluation['decisions'] = array();
			$evaluation['counts'] = array();
			$evaluation['blockers'] = isset( $evaluation['blockers'] ) && is_array( $evaluation['blockers'] ) ? $evaluation['blockers'] : array();
			if ( ! $identity_stable ) $evaluation['blockers'][] = 'snapshot_runtime_identity_changed_during_evaluation';
			if ( ! $dynamic_surface_stable ) $evaluation['blockers'][] = 'snapshot_dynamic_surface_changed_during_evaluation';
			if ( ! $census_stable ) {
				$evaluation['blockers'][] = 'snapshot_runtime_census_changed_during_evaluation';
				$evaluation['blockers'] = array_merge( $evaluation['blockers'], isset( $end_census['blockers'] ) ? (array) $end_census['blockers'] : array() );
			}
			$evaluation['blockers'] = array_values( array_unique( array_filter( array_map( 'sanitize_key', $evaluation['blockers'] ) ) ) );
		}
		$evaluation_followup = isset( $evaluation['decision_handoff'] ) && is_array( $evaluation['decision_handoff'] ) ? $evaluation['decision_handoff'] : self::evaluation_followup_handoff( isset( $evaluation['decisions'] ) && is_array( $evaluation['decisions'] ) ? $evaluation['decisions'] : array() );
		$handoff = array(
			'contract' => 'mad4b.functional-gap-decision-handoff.v1',
			'source_commit_sha' => isset( $repository['source_commit_sha'] ) ? (string) $repository['source_commit_sha'] : '',
			'build_fingerprint' => isset( $repository['build_fingerprint'] ) ? (string) $repository['build_fingerprint'] : '',
			'package_manifest_digest' => isset( $repository['package_manifest_digest'] ) ? (string) $repository['package_manifest_digest'] : '',
			'repository_evidence_sha256' => isset( $repository['evidence_sha256'] ) ? (string) $repository['evidence_sha256'] : '',
			'policy_sha256' => isset( $repository['policy_sha256'] ) ? (string) $repository['policy_sha256'] : '',
			'snapshot_identity_sha256' => $key,
			'snapshot_end_identity_sha256' => $end_key,
			'snapshot_fixed_point_stable' => $fixed_point_stable,
			'snapshot_fixed_point_attempts' => self::$fixed_point_retry_depth + 1,
			'snapshot_census_required' => $census_required,
			'snapshot_end_census_sha256' => $end_census_sha,
			'snapshot_start_dynamic_surface_sha256' => (string) $start_dynamic_surface,
			'snapshot_end_dynamic_surface_sha256' => (string) $end_dynamic_surface,
			'snapshot_dynamic_surface_stable' => $dynamic_surface_stable,
			'runtime_evidence_fingerprint' => isset( $evaluation['runtime_evidence_fingerprint'] ) ? (string) $evaluation['runtime_evidence_fingerprint'] : '',
			'runtime_census_sha256' => isset( $runtime_census['census_sha256'] ) ? (string) $runtime_census['census_sha256'] : '',
			'decision_fingerprint' => isset( $evaluation['decision_fingerprint'] ) ? (string) $evaluation['decision_fingerprint'] : '',
			'runtime_generated_at' => isset( $runtime['generated_at'] ) ? (string) $runtime['generated_at'] : '',
			'evidence_ready' => ! empty( $evaluation['ready'] ) && ! empty( $repository['valid'] ),
			'evaluation_complete' => ! empty( $evaluation['evaluation_complete'] ),
			'followup_required' => ! empty( $evaluation_followup['followup_required'] ),
			'followup_count' => isset( $evaluation_followup['followup_count'] ) ? (int) $evaluation_followup['followup_count'] : 0,
			'followup_families' => isset( $evaluation_followup['followup_families'] ) && is_array( $evaluation_followup['followup_families'] ) ? array_values( $evaluation_followup['followup_families'] ) : array(),
			'groups' => isset( $evaluation_followup['groups'] ) && is_array( $evaluation_followup['groups'] ) ? $evaluation_followup['groups'] : array(),
			'evaluation_followup' => $evaluation_followup,
			'promotion_authorized' => false,
			'mutation_authorized' => false,
			'must_revalidate_before_mutation' => true,
			'revalidation_contract' => 'recompute_current_runtime_and_require_exact_fingerprint_match',
			'blockers' => isset( $evaluation['blockers'] ) ? array_values( (array) $evaluation['blockers'] ) : array(),
		);
		self::$snapshot_key = $key;
		self::$snapshot = array(
			'contract' => self::CONTRACT,
			'snapshot_identity_sha256' => $key,
			'snapshot_end_identity_sha256' => $end_key,
			'snapshot_fixed_point_stable' => $fixed_point_stable,
			'snapshot_fixed_point_attempts' => self::$fixed_point_retry_depth + 1,
			'snapshot_census_required' => $census_required,
			'snapshot_end_census' => $end_census,
			'snapshot_start_dynamic_surface_sha256' => (string) $start_dynamic_surface,
			'snapshot_end_dynamic_surface_sha256' => (string) $end_dynamic_surface,
			'snapshot_dynamic_surface_stable' => $dynamic_surface_stable,
			'read_only' => true,
			'authority_created' => false,
			'mutation_performed' => false,
			'remote_request_performed' => false,
			'secret_values_returned' => false,
			'build_source_commit_sha' => self::build_source_commit_sha(),
			'repository_evidence' => array(
				'present' => ! empty( $repository['present'] ),
				'valid' => ! empty( $repository['valid'] ),
				'contract' => isset( $repository['contract'] ) ? $repository['contract'] : '',
				'source_commit_sha' => isset( $repository['source_commit_sha'] ) ? $repository['source_commit_sha'] : '',
				'evidence_sha256' => isset( $repository['evidence_sha256'] ) ? $repository['evidence_sha256'] : '',
				'evidence_bytes' => isset( $repository['evidence_bytes'] ) ? (int) $repository['evidence_bytes'] : 0,
				'policy_contract' => isset( $repository['policy_contract'] ) ? $repository['policy_contract'] : '',
				'policy_sha256' => isset( $repository['policy_sha256'] ) ? $repository['policy_sha256'] : '',
				'policy_bytes' => isset( $repository['policy_bytes'] ) ? (int) $repository['policy_bytes'] : 0,
				'build_fingerprint' => isset( $repository['build_fingerprint'] ) ? $repository['build_fingerprint'] : '',
				'package_manifest_digest' => isset( $repository['package_manifest_digest'] ) ? $repository['package_manifest_digest'] : '',
				'package_integrity' => isset( $repository['package_integrity'] ) && is_array( $repository['package_integrity'] ) ? $repository['package_integrity'] : array(),
				'family_count' => isset( $repository['families'] ) && is_array( $repository['families'] ) ? count( $repository['families'] ) : 0,
				'blockers' => isset( $repository['blockers'] ) ? $repository['blockers'] : array(),
			),
			'runtime' => $runtime,
			'runtime_census' => $runtime_census,
			'evaluation' => $evaluation,
			'decision_handoff' => $handoff,
		);
		return self::$snapshot;
	}

	public static function decision_handoff() {
		$snapshot = self::snapshot();
		return isset( $snapshot['decision_handoff'] ) && is_array( $snapshot['decision_handoff'] ) ? $snapshot['decision_handoff'] : array(
			'contract' => 'mad4b.functional-gap-decision-handoff.v1',
			'evidence_ready' => false,
			'evaluation_complete' => false,
			'followup_required' => true,
			'followup_count' => 0,
			'followup_families' => array(),
			'groups' => array(),
			'evaluation_followup' => array(),
			'promotion_authorized' => false,
			'mutation_authorized' => false,
			'must_revalidate_before_mutation' => true,
			'blockers' => array( 'functional_gap_decision_handoff_unavailable' ),
		);
	}

	private static function decision_map_from_snapshot( array $snapshot ) {
		$evaluation = isset( $snapshot['evaluation'] ) && is_array( $snapshot['evaluation'] ) ? $snapshot['evaluation'] : array();
		$map = array();
		foreach ( isset( $evaluation['decisions'] ) && is_array( $evaluation['decisions'] ) ? $evaluation['decisions'] : array() as $row ) {
			if ( ! is_array( $row ) || empty( $row['family'] ) ) continue;
			$map[ sanitize_key( (string) $row['family'] ) ] = $row;
		}
		ksort( $map, SORT_STRING );
		return $map;
	}

	public static function decision_map() {
		return self::decision_map_from_snapshot( self::snapshot() );
	}

	public static function current_runtime_identity_sha256() {
		return self::runtime_identity_key();
	}

	private static function summary_from_snapshot( array $snapshot ) {
		$evaluation = isset( $snapshot['evaluation'] ) && is_array( $snapshot['evaluation'] ) ? $snapshot['evaluation'] : array();
		$repository = isset( $snapshot['repository_evidence'] ) && is_array( $snapshot['repository_evidence'] ) ? $snapshot['repository_evidence'] : array();
		$counts = isset( $evaluation['counts'] ) && is_array( $evaluation['counts'] ) ? $evaluation['counts'] : array();
		$package_integrity = isset( $repository['package_integrity'] ) && is_array( $repository['package_integrity'] ) ? $repository['package_integrity'] : array();
		$runtime_budget = isset( $snapshot['runtime']['scan_budget'] ) && is_array( $snapshot['runtime']['scan_budget'] ) ? $snapshot['runtime']['scan_budget'] : array();
		$handoff = isset( $snapshot['decision_handoff'] ) && is_array( $snapshot['decision_handoff'] ) ? $snapshot['decision_handoff'] : array();
		return array(
			'contract' => self::CONTRACT,
			'snapshot_identity_sha256' => isset( $snapshot['snapshot_identity_sha256'] ) ? $snapshot['snapshot_identity_sha256'] : '',
			'snapshot_end_identity_sha256' => isset( $snapshot['snapshot_end_identity_sha256'] ) ? $snapshot['snapshot_end_identity_sha256'] : '',
			'snapshot_fixed_point_stable' => ! empty( $snapshot['snapshot_fixed_point_stable'] ),
			'snapshot_fixed_point_attempts' => isset( $snapshot['snapshot_fixed_point_attempts'] ) ? (int) $snapshot['snapshot_fixed_point_attempts'] : 0,
			'snapshot_census_required' => ! empty( $snapshot['snapshot_census_required'] ),
			'snapshot_dynamic_surface_stable' => ! empty( $snapshot['snapshot_dynamic_surface_stable'] ),
			'snapshot_end_dynamic_surface_sha256' => isset( $snapshot['snapshot_end_dynamic_surface_sha256'] ) ? (string) $snapshot['snapshot_end_dynamic_surface_sha256'] : '',
			'ready' => ! empty( $evaluation['ready'] ) && ! empty( $snapshot['snapshot_fixed_point_stable'] ),
			'repository_evidence_valid' => ! empty( $repository['valid'] ),
			'evidence_integrity_bound' => ! empty( $repository['valid'] ) && ! empty( $repository['evidence_sha256'] ) && ! empty( $repository['policy_sha256'] ) && ! empty( $repository['build_fingerprint'] ) && ! empty( $repository['package_manifest_digest'] ),
			'package_self_consistent' => ! empty( $repository['package_integrity']['valid'] ),
			'package_integrity_level' => isset( $repository['package_integrity']['integrity_level'] ) ? $repository['package_integrity']['integrity_level'] : 'unknown',
			'package_integrity_elapsed_ms' => isset( $package_integrity['elapsed_ms'] ) ? (int) $package_integrity['elapsed_ms'] : 0,
			'package_verified_file_count' => isset( $package_integrity['verified_file_count'] ) ? (int) $package_integrity['verified_file_count'] : 0,
			'package_verified_bytes' => isset( $package_integrity['verified_bytes'] ) ? (int) $package_integrity['verified_bytes'] : 0,
			'runtime_scan_elapsed_ms' => isset( $runtime_budget['elapsed_ms'] ) ? (int) $runtime_budget['elapsed_ms'] : 0,
			'runtime_scan_files_hashed' => isset( $runtime_budget['files_hashed'] ) ? (int) $runtime_budget['files_hashed'] : 0,
			'runtime_scan_bytes_hashed' => isset( $runtime_budget['bytes_hashed'] ) ? (int) $runtime_budget['bytes_hashed'] : 0,
			'external_cryptographic_attestation' => false,
			'policy_sha256' => isset( $repository['policy_sha256'] ) ? $repository['policy_sha256'] : '',
			'evidence_sha256' => isset( $repository['evidence_sha256'] ) ? $repository['evidence_sha256'] : '',
			'build_fingerprint' => isset( $repository['build_fingerprint'] ) ? $repository['build_fingerprint'] : '',
			'package_manifest_digest' => isset( $repository['package_manifest_digest'] ) ? $repository['package_manifest_digest'] : '',
			'runtime_evidence_fingerprint' => isset( $evaluation['runtime_evidence_fingerprint'] ) ? $evaluation['runtime_evidence_fingerprint'] : '',
			'runtime_census_sha256' => isset( $snapshot['runtime_census']['census_sha256'] ) ? (string) $snapshot['runtime_census']['census_sha256'] : '',
			'runtime_census_valid' => ! empty( $snapshot['runtime_census']['valid'] ),
			'decision_fingerprint' => isset( $evaluation['decision_fingerprint'] ) ? $evaluation['decision_fingerprint'] : '',
			'decision_handoff' => $handoff,
			'promotion_authorized' => false,
			'counts' => $counts,
			'unstable_family_count' => isset( $counts['runtime_evidence_unstable'] ) ? (int) $counts['runtime_evidence_unstable'] : 0,
			'blockers' => isset( $evaluation['blockers'] ) ? $evaluation['blockers'] : array(),
		);
	}

	public static function summary() {
		return self::summary_from_snapshot( self::snapshot() );
	}

	public static function coverage_projection() {
		$snapshot = self::snapshot();
		return array(
			'contract' => 'mad4b.functional-gap-coverage-projection.v1',
			'snapshot_identity_sha256' => isset( $snapshot['snapshot_identity_sha256'] ) ? (string) $snapshot['snapshot_identity_sha256'] : '',
			'snapshot_end_identity_sha256' => isset( $snapshot['snapshot_end_identity_sha256'] ) ? (string) $snapshot['snapshot_end_identity_sha256'] : '',
			'snapshot_fixed_point_stable' => ! empty( $snapshot['snapshot_fixed_point_stable'] ),
			'snapshot_fixed_point_attempts' => isset( $snapshot['snapshot_fixed_point_attempts'] ) ? (int) $snapshot['snapshot_fixed_point_attempts'] : 0,
			'snapshot_census_required' => ! empty( $snapshot['snapshot_census_required'] ),
			'snapshot_dynamic_surface_stable' => ! empty( $snapshot['snapshot_dynamic_surface_stable'] ),
			'snapshot_end_dynamic_surface_sha256' => isset( $snapshot['snapshot_end_dynamic_surface_sha256'] ) ? (string) $snapshot['snapshot_end_dynamic_surface_sha256'] : '',
			'runtime_census' => isset( $snapshot['runtime_census'] ) && is_array( $snapshot['runtime_census'] ) ? $snapshot['runtime_census'] : array(),
			'summary' => self::summary_from_snapshot( $snapshot ),
			'decisions' => self::decision_map_from_snapshot( $snapshot ),
			'promotion_authorized' => false,
			'mutation_authorized' => false,
		);
	}
